unicorn_guardian_statue.source:
export const envelope = [22, 44, 24];

export default function build(api) {
  const [W, H, D] = api.size;
  const SEAT_Y = 8;

  // Theme-aware palette with pristine quartz & arcane sea-bastion defaults
  const stonePrimary = api.theme?.stone?.primary || "minecraft:smooth_quartz";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:prismarine_bricks";
  const plinthBlock = api.theme?.ground?.plinth || "minecraft:quartz_bricks";
  const paveBlock = api.theme?.ground?.pavement || "minecraft:smooth_quartz";
  const wallBlock = api.theme?.stone?.wall || "minecraft:prismarine_wall";

  // Sculpture-specific sacred materials
  const SQ = "minecraft:smooth_quartz";
  const QB = "minecraft:quartz_block";
  const QBRK = plinthBlock;
  const CQ = "minecraft:chiseled_quartz_block";
  const QPY = "minecraft:quartz_pillar[axis=y]";
  const QSN = "minecraft:quartz_stairs[facing=north,half=bottom]";
  const QSS = "minecraft:quartz_stairs[facing=south,half=bottom]";
  const QSE = "minecraft:quartz_stairs[facing=east,half=bottom]";
  const QSW = "minecraft:quartz_stairs[facing=west,half=bottom]";
  const QSNT = "minecraft:quartz_stairs[facing=north,half=top]";
  const QSST = "minecraft:quartz_stairs[facing=south,half=top]";
  const QSET = "minecraft:quartz_stairs[facing=east,half=top]";
  const QSWT = "minecraft:quartz_stairs[facing=west,half=top]";
  const QSLAB = "minecraft:quartz_slab[type=bottom]";
  const QSLAB_TOP = "minecraft:quartz_slab[type=top]";

  const GOLD = "minecraft:gold_block";
  const LANTERN = "minecraft:sea_lantern";
  const PRIS = "minecraft:prismarine_bricks";
  const DPSN = "minecraft:dark_prismarine_stairs[facing=north,half=bottom]";
  const DPSS = "minecraft:dark_prismarine_stairs[facing=south,half=bottom]";
  const DPSE = "minecraft:dark_prismarine_stairs[facing=east,half=bottom]";
  const DPSW = "minecraft:dark_prismarine_stairs[facing=west,half=bottom]";
  const DPSLAB = "minecraft:dark_prismarine_slab[type=bottom]";
  const PWALL = wallBlock;
  const ROD_N = "minecraft:end_rod[facing=north]";

  // 3D voxel buffer for clean composition and layering
  const grid = new Map();

  function key(x, y, z) {
    return `${x},${y},${z}`;
  }

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid.set(key(x, y, z), block);
    }
  }

  function get(x, y, z) {
    return grid.get(key(x, y, z));
  }

  function fillBox(x0, y0, z0, x1, y1, z1, block) {
    for (let x = Math.min(x0, x1); x <= Math.max(x0, x1); x++) {
      for (let y = Math.min(y0, y1); y <= Math.max(y0, y1); y++) {
        for (let z = Math.min(z0, z1); z <= Math.max(z0, z1); z++) {
          set(x, y, z, block);
        }
      }
    }
  }

  function fillSphere(cx, cy, cz, rx, ry, rz, block) {
    const minX = Math.floor(cx - rx);
    const maxX = Math.ceil(cx + rx);
    const minY = Math.floor(cy - ry);
    const maxY = Math.ceil(cy + ry);
    const minZ = Math.floor(cz - rz);
    const maxZ = Math.ceil(cz + rz);

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          const dx = (x - cx) / rx;
          const dy = (y - cy) / ry;
          const dz = (z - cz) / rz;
          if (dx * dx + dy * dy + dz * dz <= 1.0) {
            set(x, y, z, block);
          }
        }
      }
    }
  }

  // --- 1. FORTIFIED COASTAL BASTION PEDESTAL ---
  // A Renaissance coastal wedge bastion thrusting North into the strait
  const CX = 11;
  const CZ = 13;

  function inBastionFootprint(x, z, y) {
    const dx = x - CX;
    const dz = z - CZ;
    let baseR = 6.6;

    // Batter slope outward into the cliff
    if (y < SEAT_Y) {
      baseR += (SEAT_Y - y) * 0.48;
    } else if (y <= 12) {
      baseR -= (y - SEAT_Y) * 0.12;
    } else if (y === 13) {
      baseR += 0.6; // Machicolation overhang
    } else if (y >= 14) {
      baseR += 0.8; // Deck & parapet
    }

    // Main rounded bastion turret
    if (dx * dx + dz * dz <= baseR * baseR) return true;

    // Northern prow wedge pointed straight at the pirate sea
    if (z <= CZ) {
      const distFromCenter = CZ - z;
      const maxWedgeWidth = (baseR + 2.0 - distFromCenter) * 0.72;
      if (distFromCenter <= baseR + 2.4 && Math.abs(dx) <= maxWedgeWidth) {
        return true;
      }
    }

    // Corner defensive buttresses
    const bx = Math.abs(dx) - 4.2;
    const bz = Math.abs(dz) - 4.2;
    if (bx * bx + bz * bz <= (y < SEAT_Y ? 3.0 : 2.2)) return true;

    return false;
  }

  // Build Bastion Foundation & Skirt (Conforming to terrain via heightAt)
  for (let x = 1; x < W - 1; x++) {
    for (let z = 1; z < D - 1; z++) {
      if (inBastionFootprint(x, z, SEAT_Y)) {
        const th = api.heightAt(x, z);
        const groundY = Math.max(0, Math.min(SEAT_Y, SEAT_Y + Math.round(th)));

        // Skirt from real ground up to bastion deck
        for (let y = groundY; y <= 14; y++) {
          if (inBastionFootprint(x, z, y)) {
            const isPerimeter =
              !inBastionFootprint(x + 1, z, y) ||
              !inBastionFootprint(x - 1, z, y) ||
              !inBastionFootprint(x, z + 1, y) ||
              !inBastionFootprint(x, z - 1, y);

            if (y < SEAT_Y) {
              set(x, y, z, isPerimeter ? QBRK : stonePrimary);
            } else if (y === 8) {
              set(x, y, z, paveBlock);
            } else if (y <= 13) {
              set(x, y, z, isPerimeter ? stonePrimary : QB);
            }
          }
        }
      }
    }
  }

  // Carve Vault interior inside the bastion (Standable volume Y: 9..13)
  for (let x = 8; x <= 14; x++) {
    for (let z = 10; z <= 16; z++) {
      for (let y = 9; y <= 13; y++) {
        grid.delete(key(x, y, z));
      }
    }
  }

  // Vault arched ceiling supports & South entrance gate
  for (let y = 9; y <= 11; y++) {
    grid.delete(key(11, y, 18));
    grid.delete(key(11, y, 19));
    grid.delete(key(11, y, 20));
  }
  set(10, 9, 20, QPY);
  set(10, 10, 20, QPY);
  set(10, 11, 20, QSN);
  set(12, 9, 20, QPY);
  set(12, 10, 20, QPY);
  set(12, 11, 20, QSN);
  set(11, 12, 20, CQ);

  // Northern Cannon/Ballista Arrow-Slit Embrasures at Y = 10..11
  grid.delete(key(11, 10, 6));
  grid.delete(key(11, 11, 6));
  set(10, 10, 6, QSE);
  set(12, 10, 6, QSW);
  set(11, 12, 6, CQ);

  // Machicolations at Y = 13 (Cornice overhang)
  for (let x = 1; x < W - 1; x++) {
    for (let z = 1; z < D - 1; z++) {
      if (inBastionFootprint(x, z, 13) && !inBastionFootprint(x, z, 12)) {
        if (z < CZ) set(x, 13, z, QSNT);
        else if (z > CZ) set(x, 13, z, QSST);
        else if (x < CX) set(x, 13, z, QSWT);
        else set(x, 13, z, QSET);
      }
    }
  }

  // Bastion Deck Floor Pattern at Y = 14
  for (let x = 2; x < W - 2; x++) {
    for (let z = 2; z < D - 2; z++) {
      if (inBastionFootprint(x, z, 14)) {
        const d = Math.hypot(x - CX, z - CZ);
        if (d < 1.6) {
          set(x, 14, z, LANTERN);
        } else if (d < 3.2) {
          set(x, 14, z, PRIS);
        } else if (d < 5.0) {
          set(x, 14, z, CQ);
        } else {
          set(x, 14, z, SQ);
        }
      }
    }
  }

  // Bastion Parapet & Crenellations at Y = 14..15
  for (let x = 2; x < W - 2; x++) {
    for (let z = 2; z < D - 2; z++) {
      if (inBastionFootprint(x, z, 14)) {
        const isEdge =
          !inBastionFootprint(x + 1, z, 14) ||
          !inBastionFootprint(x - 1, z, 14) ||
          !inBastionFootprint(x, z + 1, 14) ||
          !inBastionFootprint(x, z - 1, 14);

        if (isEdge) {
          if ((x + z) % 2 === 0) {
            set(x, 15, z, CQ);
            set(x, 16, z, DPSLAB);
          } else {
            set(x, 15, z, PWALL);
          }
        }
      }
    }
  }

  // Four Fortified Sea-Beacon Towers at deck corners
  const beaconCoords = [
    [6, 8],
    [16, 8],
    [6, 18],
    [16, 18],
    [11, 5],
  ];
  for (const [bx, bz] of beaconCoords) {
    set(bx, 14, bz, CQ);
    set(bx, 15, bz, LANTERN);
    set(bx, 16, bz, QSLAB);
  }

  // --- 2. COLOSSAL REARING UNICORN GUARDIAN ---

  // A. HINDQUARTERS & GOLDEN HOOVES (Anchored firmly on Bastion Deck at Y = 14)
  // Left Hind Hoof & Leg (X = 8)
  fillBox(8, 14, 15, 9, 14, 16, GOLD);
  set(7, 14, 15, QSE);
  set(7, 14, 16, QSE);
  set(8, 14, 17, QSN);
  set(9, 14, 17, QSN);
  fillBox(8, 15, 15, 9, 15, 16, SQ);
  fillBox(8, 16, 15, 8, 18, 15, QPY);
  set(8, 18, 16, QSN); // Hock joint
  fillBox(7, 19, 14, 9, 23, 16, SQ); // Left thigh muscle

  // Right Hind Hoof & Leg (X = 13..14)
  fillBox(13, 14, 15, 14, 14, 16, GOLD);
  set(15, 14, 15, QSW);
  set(15, 14, 16, QSW);
  set(13, 14, 17, QSN);
  set(14, 14, 17, QSN);
  fillBox(13, 15, 15, 14, 15, 16, SQ);
  fillBox(14, 16, 15, 14, 18, 15, QPY);
  set(14, 18, 16, QSN); // Hock joint
  fillBox(13, 19, 14, 15, 23, 16, SQ); // Right thigh muscle

  // B. FLOWING ARCANE TAIL (Third structural anchor brace to Bastion Deck)
  // Cascades from rump (Z=17, Y=25) down to the deck (Z=17..19, Y=14)
  fillBox(10, 24, 16, 12, 25, 17, SQ);
  fillBox(10, 22, 17, 12, 24, 18, PRIS);
  fillBox(10, 19, 18, 12, 22, 19, PRIS);
  fillBox(9, 16, 17, 13, 19, 19, PRIS);
  fillBox(9, 14, 16, 13, 15, 19, PRIS);

  // Tail glow & dynamic locks
  set(11, 20, 18, LANTERN);
  set(11, 16, 18, LANTERN);
  set(9, 18, 18, DPSW);
  set(13, 18, 18, DPSE);
  set(9, 15, 17, DPSW);
  set(13, 15, 17, DPSE);
  set(10, 14, 19, DPSN);
  set(11, 14, 19, DPSN);
  set(12, 14, 19, DPSN);

  // C. PELVIS, FLANK, AND BARREL (Rearing torso angled forward-up)
  for (let y = 22; y <= 29; y++) {
    const t = (y - 22) / 7.0;
    const cy = y;
    const cx = CX;
    const cz = 15.0 * (1 - t) + 8.5 * t;
    const rx = 2.4 + 0.6 * Math.sin(t * Math.PI);
    const rz = 2.0 + 0.5 * Math.sin(t * Math.PI);

    for (let x = Math.floor(cx - rx - 1); x <= Math.ceil(cx + rx + 1); x++) {
      for (let z = Math.floor(cz - rz - 1); z <= Math.ceil(cz + rz + 1); z++) {
        const dx = (x - cx) / rx;
        const dz = (z - cz) / rz;
        if (dx * dx + dz * dz <= 1.05) {
          set(x, cy, z, SQ);
        }
      }
    }
  }

  // D. CHEST & ARCANE MEDALLION (Pushing forward toward the sea)
  fillSphere(11, 28, 8, 2.8, 2.2, 2.0, SQ);

  // The Grand Medallion of the Unicorn Isle on the breast
  set(11, 28, 6, LANTERN);
  set(10, 28, 6, GOLD);
  set(12, 28, 6, GOLD);
  set(11, 29, 6, GOLD);
  set(11, 27, 6, GOLD);
  set(10, 29, 6, CQ);
  set(12, 29, 6, CQ);
  set(10, 27, 6, CQ);
  set(12, 27, 6, CQ);

  // E. RADIANT ASTRAL FLANK CRESTS (Guardian Wing-Plates)
  // Left wing crest
  set(7, 28, 9, GOLD);
  set(6, 29, 9, PRIS);
  set(6, 30, 10, SQ);
  set(5, 31, 11, QSLAB);
  set(6, 28, 10, DPSW);
  // Right wing crest
  set(15, 28, 9, GOLD);
  set(16, 29, 9, PRIS);
  set(16, 30, 10, SQ);
  set(17, 31, 11, QSLAB);
  set(16, 28, 10, DPSE);

  // F. FORELEGS (Rearing high and striking down toward the pirate strait)
  // Left Foreleg (bent ready to strike)
  fillBox(7, 27, 7, 8, 28, 8, SQ); // Shoulder
  fillBox(7, 26, 6, 7, 27, 6, SQ); // Upper arm
  fillBox(7, 27, 5, 8, 28, 5, SQ); // Forearm
  set(7, 28, 4, CQ); // Knee
  fillBox(7, 26, 3, 7, 27, 4, SQ); // Cannon
  set(7, 25, 3, SQ);
  set(7, 24, 3, GOLD); // Golden Left Hoof
  set(7, 24, 2, GOLD);
  set(7, 25, 2, QSN);

  // Right Foreleg (extended high in defiant war strike)
  fillBox(14, 28, 7, 15, 29, 8, SQ); // Shoulder
  fillBox(14, 29, 6, 15, 30, 6, SQ); // Upper arm
  fillBox(14, 30, 5, 15, 31, 5, SQ); // Forearm
  set(15, 32, 4, CQ); // Knee
  fillBox(15, 31, 3, 15, 32, 3, SQ); // Cannon
  set(15, 30, 2, GOLD); // Golden Right Hoof
  set(15, 31, 2, GOLD);
  set(15, 32, 2, QSN);

  // G. ARCHED NECK & THROAT
  for (let y = 29; y <= 35; y++) {
    const t = (y - 29) / 6.0;
    const cy = y;
    const cx = CX;
    const cz = 7.8 * (1 - t) + 4.8 * t;
    const rx = 1.6 - t * 0.3;
    const rz = 1.6 - t * 0.3;

    for (let x = Math.floor(cx - rx - 1); x <= Math.ceil(cx + rx + 1); x++) {
      for (let z = Math.floor(cz - rz - 1); z <= Math.ceil(cz + rz + 1); z++) {
        const dx = (x - cx) / rx;
        const dz = (z - cz) / rz;
        if (dx * dx + dz * dz <= 1.0) {
          set(x, cy, z, SQ);
        }
      }
    }
  }

  // H. ENCHANTED FLOWING MANE (Spilling back & east in the sea wind)
  fillBox(11, 30, 8, 12, 31, 9, PRIS);
  fillBox(11, 32, 7, 12, 33, 8, PRIS);
  fillBox(11, 34, 6, 12, 35, 7, PRIS);
  set(11, 36, 6, PRIS);
  set(12, 35, 6, LANTERN);
  set(12, 33, 7, LANTERN);
  set(13, 34, 7, DPSE);
  set(13, 32, 8, DPSE);
  set(12, 30, 9, DPSS);

  // I. HEAD, NOBLE JAW, AND MUZZLE (Glaring North at the fleet)
  fillBox(10, 34, 4, 12, 36, 6, SQ); // Cranium
  fillBox(10, 33, 3, 12, 34, 5, SQ); // Jaw & cheeks
  fillBox(10, 34, 2, 12, 34, 3, SQ); // Snout
  set(11, 33, 2, QSN); // Parted mouth

  // Flared nostrils
  set(10, 34, 1, CQ);
  set(12, 34, 1, CQ);

  // Radiant Arcane Eyes (Glaring down at the corsairs)
  set(9, 35, 4, LANTERN);
  set(13, 35, 4, LANTERN);
  set(9, 36, 4, QSE);
  set(13, 36, 4, QSW);

  // Pointed Alert Ears
  set(10, 37, 5, QSS);
  set(10, 38, 5, QSLAB);
  set(12, 37, 5, QSS);
  set(12, 38, 5, QSLAB);

  // J. THE GRAND ALICORN HORN (Tipped with radiant gold & sea light)
  // Emerges from forehead at (11, 35, 3) and thrusts forward-upward
  set(11, 35, 3, CQ); // Horn socket
  set(10, 35, 3, PWALL);
  set(12, 35, 3, PWALL);

  set(11, 36, 3, GOLD);
  set(11, 36, 4, DPSN);

  set(11, 37, 2, LANTERN);
  set(10, 37, 2, PWALL);
  set(12, 37, 2, PWALL);

  set(11, 38, 2, GOLD);
  set(11, 39, 1, LANTERN);
  set(11, 40, 1, GOLD);
  set(11, 41, 0, ROD_N); // Piercing luminous tip

  // Emit all staged blocks deterministically
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const b = get(x, y, z);
        if (b) {
          api.set(x, y, z, b);
        }
      }
    }
  }

  return {
    name: "Unicorn Guardian Colossus",
    seatY: SEAT_Y,
    anchors: {
      front: [11, SEAT_Y, 0],
      door: [11, SEAT_Y, 20],
      lookout: [11, 14, 5],
      horn: [11, 41, 0],
    },
    interiors: [
      {
        min: [8, 9, 10],
        max: [14, 13, 16],
        kind: "vault",
      },
    ],
  };
}

pirate_dreadnought_flagship.source:
export const envelope = [17, 36, 51];

export default function build(api) {
  const W = envelope[0];
  const H = envelope[1];
  const D = envelope[2];

  // Palette from world theme
  const woodPlanks = api.theme.wood.planks || "minecraft:dark_oak_planks";
  const woodLog = api.theme.wood.log || "minecraft:dark_oak_log";
  const woodStripped = api.theme.wood.stripped || "minecraft:stripped_dark_oak_log";
  const woodStairs = api.theme.wood.stairs || "minecraft:dark_oak_stairs";
  const woodSlab = api.theme.wood.slab || "minecraft:dark_oak_slab";
  const woodFence = api.theme.wood.fence || "minecraft:dark_oak_fence";
  const woodTrapdoor = api.theme.wood.trapdoor || "minecraft:dark_oak_trapdoor";
  const woodDoor = api.theme.wood.door || "minecraft:dark_oak_door";
  const stonePrimary = api.theme.stone.primary || "minecraft:stone_bricks";

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(Math.floor(x), Math.floor(y), Math.floor(z), block);
    }
  }

  // Hull half-width profile
  function getHullHalfWidth(z, y) {
    if (z < 6 || z > 47) return -1;
    if (y < 6 || y > 22) return -1;

    let maxDeckY = 17;
    if (z <= 14) maxDeckY = 16 + (14 - z) * 0.25;
    else if (z >= 34 && z <= 41) maxDeckY = 17 + (z - 33) * 0.25;
    else if (z >= 42) maxDeckY = 22;

    if (y > maxDeckY) return -1;

    let zFactor = 1.0;
    if (z < 15) {
      zFactor = Math.sin(((z - 6) / 9) * (Math.PI / 2));
    } else if (z > 36) {
      zFactor = 0.85 + 0.15 * Math.cos(((z - 36) / 11) * Math.PI);
    }

    let yFactor = 0.2;
    if (y === 6) {
      yFactor = 0.2;
    } else if (y <= 10) {
      yFactor = 0.2 + 0.8 * ((y - 6) / 4);
    } else if (y <= 15) {
      yFactor = 1.0;
    } else {
      if (z >= 38) {
        yFactor = 1.05;
      } else {
        yFactor = 0.95;
      }
    }

    return 5.2 * zFactor * yFactor;
  }

  const cx = 8;
  const seatY = 6;

  // 1. Foundation / Seabed conformance (Rule 6 & Rule 5)
  for (let z = 6; z <= 47; z++) {
    const hw6 = Math.max(0, Math.floor(getHullHalfWidth(z, seatY)));
    for (let dx = -hw6; dx <= hw6; dx++) {
      const x = cx + dx;
      const hLocal = Math.floor(api.heightAt(x, z));
      const groundY = Math.min(seatY, Math.max(0, seatY + hLocal));
      for (let y = groundY; y < seatY; y++) {
        setBlock(x, y, z, dx === 0 ? woodLog : woodPlanks);
      }
    }
  }

  // 2. Keel, Stempost, and Sternpost
  for (let z = 6; z <= 47; z++) {
    setBlock(cx, seatY, z, woodLog);
  }
  for (let y = seatY; y <= 17; y++) {
    setBlock(cx, y, 6, woodLog);
  }
  for (let y = seatY; y <= 16; y++) {
    setBlock(cx, y, 47, woodLog);
  }
  // Rudder
  for (let y = seatY; y <= 14; y++) {
    setBlock(cx, y, 48, woodPlanks);
    setBlock(cx - 1, y, 48, "minecraft:dark_oak_trapdoor[facing=west,open=false]");
    setBlock(cx + 1, y, 48, "minecraft:dark_oak_trapdoor[facing=east,open=false]");
  }

  // 3. Hull Shell Construction
  for (let z = 6; z <= 47; z++) {
    for (let y = seatY; y <= 22; y++) {
      const hw = getHullHalfWidth(z, y);
      if (hw < 0) continue;
      const iHw = Math.floor(hw);

      for (let dx = -iHw; dx <= iHw; dx++) {
        const x = cx + dx;
        const isOuter = (Math.abs(dx) >= iHw - 0.5) || (z === 6) || (z === 47);

        if (isOuter) {
          if (y === seatY || y === 10 || y === 14) {
            setBlock(x, y, z, woodLog);
          } else {
            setBlock(x, y, z, woodPlanks);
          }
        }
      }
    }
  }

  // 4. Deck Floors
  // Lower Hold Deck (y = 6)
  for (let z = 16; z <= 34; z++) {
    for (let dx = -3; dx <= 3; dx++) {
      setBlock(cx + dx, 6, z, stonePrimary);
    }
  }

  // Main Gun Deck Floor (y = 10)
  for (let z = 10; z <= 45; z++) {
    const hw = Math.max(0, Math.floor(getHullHalfWidth(z, 10)) - 1);
    for (let dx = -hw; dx <= hw; dx++) {
      setBlock(cx + dx, 10, z, woodPlanks);
    }
  }

  // Waist Weather Deck Floor (y = 15)
  for (let z = 15; z <= 33; z++) {
    const hw = Math.max(0, Math.floor(getHullHalfWidth(z, 15)) - 1);
    for (let dx = -hw; dx <= hw; dx++) {
      setBlock(cx + dx, 15, z, woodStripped);
    }
  }

  // Forecastle Deck Floor (y = 17)
  for (let z = 8; z <= 14; z++) {
    const hw = Math.max(0, Math.floor(getHullHalfWidth(z, 17)) - 1);
    for (let dx = -hw; dx <= hw; dx++) {
      setBlock(cx + dx, 17, z, woodPlanks);
    }
  }

  // Quarterdeck Floor (y = 18)
  for (let z = 34; z <= 41; z++) {
    const hw = Math.max(0, Math.floor(getHullHalfWidth(z, 18)) - 1);
    for (let dx = -hw; dx <= hw; dx++) {
      setBlock(cx + dx, 18, z, woodPlanks);
    }
  }

  // Poop Deck Floor (y = 21)
  for (let z = 42; z <= 47; z++) {
    const hw = Math.max(0, Math.floor(getHullHalfWidth(z, 21)) - 1);
    for (let dx = -hw; dx <= hw; dx++) {
      setBlock(cx + dx, 21, z, woodPlanks);
    }
  }

  // 5. Carve Interior Air Volumes for Compiler Furnishing
  // Hold (y = 7..9, z = 18..32)
  for (let z = 18; z <= 32; z++) {
    for (let y = 7; y <= 9; y++) {
      for (let x = cx - 2; x <= cx + 2; x++) {
        setBlock(x, y, z, "minecraft:air");
      }
    }
  }

  // Gun Deck (y = 11..14, z = 16..34)
  for (let z = 16; z <= 34; z++) {
    for (let y = 11; y <= 14; y++) {
      for (let x = cx - 3; x <= cx + 3; x++) {
        setBlock(x, y, z, "minecraft:air");
      }
    }
  }

  // Captain's Great Cabin (y = 16..20, z = 36..45)
  for (let z = 36; z <= 45; z++) {
    for (let y = 16; y <= 20; y++) {
      for (let x = cx - 3; x <= cx + 3; x++) {
        setBlock(x, y, z, "minecraft:air");
      }
    }
  }

  // 6. Bulkheads and Cabin Partitions
  // Fore gun deck bulkhead (z = 15)
  for (let y = 11; y <= 14; y++) {
    for (let dx = -3; dx <= 3; dx++) {
      if (dx === 0 && (y === 11 || y === 12)) {
        setBlock(cx, y, 15, "minecraft:air");
      } else {
        setBlock(cx + dx, y, 15, woodPlanks);
      }
    }
  }

  // Aft gun deck bulkhead (z = 35)
  for (let y = 11; y <= 14; y++) {
    for (let dx = -3; dx <= 3; dx++) {
      if (dx === 0 && (y === 11 || y === 12)) {
        setBlock(cx, y, 35, "minecraft:air");
      } else {
        setBlock(cx + dx, y, 35, woodPlanks);
      }
    }
  }

  // Captain's Cabin forward wall (z = 35, y = 16..18)
  for (let y = 16; y <= 18; y++) {
    for (let dx = -3; dx <= 3; dx++) {
      if (dx === 0 && (y === 16 || y === 17)) {
        setBlock(cx, y, 35, "minecraft:air");
      } else {
        setBlock(cx + dx, y, 35, woodPlanks);
      }
    }
  }
  setBlock(cx, 16, 35, woodDoor);

  // 7. Staircases and Deck Access
  // Waist to Gun Deck central companionway
  setBlock(cx, 15, 18, "minecraft:air");
  setBlock(cx, 15, 19, "minecraft:air");
  setBlock(cx, 15, 20, "minecraft:air");
  setBlock(cx, 14, 18, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
  setBlock(cx, 13, 19, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
  setBlock(cx, 12, 20, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
  setBlock(cx, 11, 21, "minecraft:dark_oak_stairs[facing=north,half=bottom]");

  // Gun deck to Hold ladder
  setBlock(cx, 10, 23, "minecraft:air");
  for (let y = 7; y <= 10; y++) {
    setBlock(cx, y, 23, "minecraft:ladder[facing=north]");
  }

  // Waist to Forecastle stairs
  setBlock(cx - 3, 16, 15, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
  setBlock(cx - 3, 17, 14, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
  setBlock(cx + 3, 16, 15, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
  setBlock(cx + 3, 17, 14, "minecraft:dark_oak_stairs[facing=north,half=bottom]");

  // Waist to Quarterdeck stairs
  setBlock(cx - 3, 16, 33, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
  setBlock(cx - 3, 17, 34, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
  setBlock(cx + 3, 16, 33, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
  setBlock(cx + 3, 17, 34, "minecraft:dark_oak_stairs[facing=south,half=bottom]");

  // Quarterdeck to Poop deck stairs
  setBlock(cx - 3, 19, 41, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
  setBlock(cx - 3, 20, 42, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
  setBlock(cx + 3, 19, 41, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
  setBlock(cx + 3, 20, 42, "minecraft:dark_oak_stairs[facing=south,half=bottom]");

  // 8. Broadside Cannons and Gunports
  const broadsideZ = [18, 22, 26, 30, 34];
  for (const gz of broadsideZ) {
    const hw = Math.floor(getHullHalfWidth(gz, 12));
    const portX = cx - hw;
    const stbdX = cx + hw;

    // Port cannon
    setBlock(portX, 12, gz, "minecraft:dispenser[facing=west]");
    setBlock(portX + 1, 11, gz, woodStairs);
    setBlock(portX, 13, gz, woodTrapdoor);

    // Starboard cannon
    setBlock(stbdX, 12, gz, "minecraft:dispenser[facing=east]");
    setBlock(stbdX - 1, 11, gz, woodStairs);
    setBlock(stbdX, 13, gz, woodTrapdoor);
  }

  // Forecastle bow chasers (facing North towards unicorn island)
  setBlock(cx - 2, 18, 8, "minecraft:dispenser[facing=north]");
  setBlock(cx + 2, 18, 8, "minecraft:dispenser[facing=north]");
  setBlock(cx - 2, 18, 9, woodStairs);
  setBlock(cx + 2, 18, 9, woodStairs);

  // Stern chasers
  setBlock(cx - 2, 22, 46, "minecraft:dispenser[facing=south]");
  setBlock(cx + 2, 22, 46, "minecraft:dispenser[facing=south]");

  // 9. Bulwarks, Parapets, and Transom Windows
  // Waist bulwarks
  for (let z = 15; z <= 33; z++) {
    const hw = Math.floor(getHullHalfWidth(z, 16));
    setBlock(cx - hw, 16, z, woodPlanks);
    setBlock(cx + hw, 16, z, woodPlanks);
    if (z % 2 === 0) {
      setBlock(cx - hw, 17, z, woodFence);
      setBlock(cx + hw, 17, z, woodFence);
    }
  }

  // Forecastle bulwarks
  for (let z = 8; z <= 14; z++) {
    const hw = Math.floor(getHullHalfWidth(z, 18));
    setBlock(cx - hw, 18, z, woodFence);
    setBlock(cx + hw, 18, z, woodFence);
  }

  // Quarterdeck and Poop bulwarks
  for (let z = 34; z <= 41; z++) {
    const hw = Math.floor(getHullHalfWidth(z, 19));
    setBlock(cx - hw, 19, z, woodFence);
    setBlock(cx + hw, 19, z, woodFence);
  }
  for (let z = 42; z <= 47; z++) {
    const hw = Math.floor(getHullHalfWidth(z, 22));
    setBlock(cx - hw, 22, z, woodFence);
    setBlock(cx + hw, 22, z, woodFence);
  }
  for (let x = cx - 3; x <= cx + 3; x++) {
    setBlock(x, 22, 47, woodFence);
  }

  // Transom Stern Gallery Windows (z = 47, y = 17..19)
  for (let y = 17; y <= 19; y++) {
    for (let dx = -3; dx <= 3; dx++) {
      if (Math.abs(dx) % 2 === 1) {
        setBlock(cx + dx, y, 47, "minecraft:iron_bars");
      } else {
        setBlock(cx + dx, y, 47, woodLog);
      }
    }
  }

  // Stern balcony
  for (let dx = -3; dx <= 3; dx++) {
    setBlock(cx + dx, 16, 48, woodSlab);
    setBlock(cx + dx, 17, 48, woodFence);
  }

  // Stern lanterns
  setBlock(cx - 3, 20, 48, woodFence);
  setBlock(cx - 3, 21, 48, "minecraft:lantern[hanging=false]");
  setBlock(cx + 3, 20, 48, woodFence);
  setBlock(cx + 3, 21, 48, "minecraft:lantern[hanging=false]");
  setBlock(cx, 23, 47, woodFence);
  setBlock(cx, 24, 47, "minecraft:lantern[hanging=false]");

  // Ship's Helm on Quarterdeck
  setBlock(cx, 19, 40, woodFence);
  setBlock(cx, 20, 40, woodTrapdoor);

  // 10. Bowsprit and Ram Figurehead
  // Bowsprit extending North (-Z)
  const bowspritPoints = [
    [cx, 17, 10], [cx, 17, 9], [cx, 18, 8], [cx, 18, 7],
    [cx, 19, 6], [cx, 19, 5], [cx, 20, 4], [cx, 20, 3],
    [cx, 21, 2], [cx, 21, 1], [cx, 22, 0]
  ];
  for (const [bx, by, bz] of bowspritPoints) {
    setBlock(bx, by, bz, woodLog);
  }
  setBlock(cx, 23, 0, "minecraft:skeleton_skull");

  // Dragon Ram figurehead beneath bowsprit (z = 2..5, y = 13..16)
  setBlock(cx, 16, 5, woodLog);
  setBlock(cx, 15, 4, woodLog);
  setBlock(cx, 15, 3, woodLog);
  setBlock(cx, 14, 2, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
  setBlock(cx - 1, 15, 3, "minecraft:dark_oak_trapdoor[facing=west,open=false]");
  setBlock(cx + 1, 15, 3, "minecraft:dark_oak_trapdoor[facing=east,open=false]");
  setBlock(cx - 1, 16, 4, woodFence);
  setBlock(cx + 1, 16, 4, woodFence);

  // Anchors on bow sides
  setBlock(cx - 4, 16, 8, woodLog);
  setBlock(cx - 4, 15, 8, "minecraft:chain[axis=y]");
  setBlock(cx - 4, 14, 8, "minecraft:chain[axis=y]");
  setBlock(cx - 4, 13, 8, "minecraft:iron_bars");

  setBlock(cx + 4, 16, 8, woodLog);
  setBlock(cx + 4, 15, 8, "minecraft:chain[axis=y]");
  setBlock(cx + 4, 14, 8, "minecraft:chain[axis=y]");
  setBlock(cx + 4, 13, 8, "minecraft:iron_bars");

  // 11. Masts, Crow's Nests, Rigging, and Billowing Corsair Sails

  // --- FOREMAST (z = 14) ---
  for (let y = 10; y <= 31; y++) {
    setBlock(cx, y, 14, woodLog);
  }
  // Foremast Crow's Nest (y = 21)
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      setBlock(cx + dx, 21, 14 + dz, woodPlanks);
      if (Math.abs(dx) === 1 || Math.abs(dz) === 1) {
        setBlock(cx + dx, 22, 14 + dz, woodFence);
      }
    }
  }
  // Lower Fore Yard (y = 18)
  for (let dx = -5; dx <= 5; dx++) {
    setBlock(cx + dx, 18, 14, woodStripped);
  }
  // Billowing Foresail (y = 14..17)
  for (let y = 14; y <= 17; y++) {
    const v = (y - 14) / 3;
    const dzBillow = Math.round(-Math.sin(v * Math.PI) * 1.5);
    const hw = Math.round(4.5 * Math.sin(v * Math.PI * 0.7 + 0.3));
    for (let dx = -hw; dx <= hw; dx++) {
      const isStripe = Math.abs(dx) % 2 === 0;
      setBlock(cx + dx, y, 14 + dzBillow, isStripe ? "minecraft:black_wool" : "minecraft:gray_wool");
    }
  }
  // Upper Fore Yard (y = 26)
  for (let dx = -4; dx <= 4; dx++) {
    setBlock(cx + dx, 26, 14, woodStripped);
  }
  // Fore Topsail (y = 22..25)
  for (let y = 22; y <= 25; y++) {
    const v = (y - 22) / 3;
    const dzBillow = Math.round(-Math.sin(v * Math.PI) * 1.2);
    const hw = Math.round(3.5 * Math.sin(v * Math.PI * 0.7 + 0.3));
    for (let dx = -hw; dx <= hw; dx++) {
      setBlock(cx + dx, y, 14 + dzBillow, "minecraft:black_wool");
    }
  }

  // --- MAINMAST (z = 25) --- (Tallest mast, Jolly Roger flag)
  for (let y = 10; y <= 35; y++) {
    setBlock(cx, y, 25, woodLog);
  }
  // Main Crow's Nest (y = 23)
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      setBlock(cx + dx, 23, 25 + dz, woodPlanks);
      if (Math.abs(dx) === 1 || Math.abs(dz) === 1) {
        setBlock(cx + dx, 24, 25 + dz, woodFence);
      }
    }
  }
  // Lower Main Yard (y = 19)
  for (let dx = -6; dx <= 6; dx++) {
    setBlock(cx + dx, 19, 25, woodStripped);
  }
  // Billowing Mainsail with Skull Motif (y = 14..18)
  for (let y = 14; y <= 18; y++) {
    const v = (y - 14) / 4;
    const dzBillow = Math.round(-Math.sin(v * Math.PI) * 1.8);
    const hw = Math.round(5.5 * Math.sin(v * Math.PI * 0.7 + 0.3));
    for (let dx = -hw; dx <= hw; dx++) {
      let mat = (Math.abs(dx) % 2 === 0) ? "minecraft:black_wool" : "minecraft:gray_wool";
      // Skull centerpiece emblem
      if ((y === 16 || y === 17) && Math.abs(dx) <= 1) {
        mat = "minecraft:white_wool";
      } else if (y === 15 && Math.abs(dx) === 1) {
        mat = "minecraft:white_wool";
      }
      setBlock(cx + dx, y, 25 + dzBillow, mat);
    }
  }
  // Upper Main Topsail Yard (y = 27)
  for (let dx = -5; dx <= 5; dx++) {
    setBlock(cx + dx, 27, 25, woodStripped);
  }
  // Main Topsail (y = 24..26)
  for (let y = 24; y <= 26; y++) {
    const v = (y - 24) / 2;
    const dzBillow = Math.round(-Math.sin(v * Math.PI) * 1.2);
    const hw = Math.round(4.0 * Math.sin(v * Math.PI * 0.7 + 0.3));
    for (let dx = -hw; dx <= hw; dx++) {
      setBlock(cx + dx, y, 25 + dzBillow, "minecraft:black_wool");
    }
  }
  // Topgallant Yard (y = 32)
  for (let dx = -3; dx <= 3; dx++) {
    setBlock(cx + dx, 32, 25, woodStripped);
  }
  // Topgallant Sail (y = 29..31)
  for (let y = 29; y <= 31; y++) {
    for (let dx = -2; dx <= 2; dx++) {
      setBlock(cx + dx, y, 24, "minecraft:black_wool");
    }
  }
  // Jolly Roger Ensign at Mainmast head
  setBlock(cx, 35, 25, "minecraft:skeleton_skull");
  setBlock(cx, 34, 26, "minecraft:black_wool");
  setBlock(cx, 34, 27, "minecraft:black_wool");
  setBlock(cx, 33, 27, "minecraft:black_wool");

  // --- MIZZENMAST (z = 37) ---
  for (let y = 15; y <= 29; y++) {
    setBlock(cx, y, 37, woodLog);
  }
  // Mizzen Top (y = 23)
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      setBlock(cx + dx, 23, 37 + dz, woodPlanks);
      if (Math.abs(dx) === 1 || Math.abs(dz) === 1) {
        setBlock(cx + dx, 24, 37 + dz, woodFence);
      }
    }
  }
  // Lateen / Spanker Yard (angled spar)
  const lateenSpar = [
    [cx, 19, 34], [cx, 20, 35], [cx, 21, 36], [cx, 22, 37],
    [cx, 23, 38], [cx, 24, 39], [cx, 25, 40], [cx, 26, 41]
  ];
  for (const [lx, ly, lz] of lateenSpar) {
    setBlock(lx, ly, lz, woodStripped);
  }
  // Spanker Boom at y = 19
  for (let z = 35; z <= 42; z++) {
    setBlock(cx, 19, z, woodStripped);
  }
  // Spanker Sail Sheet
  for (let z = 35; z <= 41; z++) {
    const topY = 19 + Math.floor((z - 34) * 0.9);
    for (let y = 19; y <= topY; y++) {
      setBlock(cx, y, z, "minecraft:black_wool");
    }
  }

  // Rigging Shrouds & Stays
  // Foremast shrouds
  for (let y = 16; y <= 21; y++) {
    const t = (y - 16) / 5;
    const px = Math.round(5 - t * 4);
    setBlock(cx - px, y, 14, woodFence);
    setBlock(cx + px, y, 14, woodFence);
  }
  // Mainmast shrouds
  for (let y = 16; y <= 23; y++) {
    const t = (y - 16) / 7;
    const px = Math.round(5 - t * 4);
    setBlock(cx - px, y, 25, woodFence);
    setBlock(cx + px, y, 25, woodFence);
  }
  // Mizzen shrouds
  for (let y = 19; y <= 23; y++) {
    const t = (y - 19) / 4;
    const px = Math.round(4 - t * 3);
    setBlock(cx - px, y, 37, woodFence);
    setBlock(cx + px, y, 37, woodFence);
  }

  // Forestay chains connecting masts to bow
  setBlock(cx, 22, 8, "minecraft:chain[axis=z]");
  setBlock(cx, 23, 9, "minecraft:chain[axis=z]");
  setBlock(cx, 24, 10, "minecraft:chain[axis=z]");
  setBlock(cx, 25, 11, "minecraft:chain[axis=z]");
  setBlock(cx, 26, 12, "minecraft:chain[axis=z]");
  setBlock(cx, 27, 13, "minecraft:chain[axis=z]");

  return {
    name: "pirate_dreadnought_flagship",
    seatY: seatY,
    anchors: {
      front: [cx, 16, 0],
      helm: [cx, 19, 40],
      forecastle: [cx, 17, 10]
    },
    interiors: [
      { min: [cx - 2, 7, 18], max: [cx + 2, 9, 32], kind: "vault" },
      { min: [cx - 3, 11, 16], max: [cx + 3, 14, 34], kind: "hall" },
      { min: [cx - 3, 16, 36], max: [cx + 3, 19, 45], kind: "quarters" }
    ]
  };
}

celestial_crystal_spire.source:
export const envelope = [17, 52, 17];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 8;
  const cz = 8;
  const seatY = 6;

  // Grid buffer for deterministic assembly and bounds safety
  const grid = Array.from({ length: H }, () =>
    Array.from({ length: D }, () => new Array(W).fill(null))
  );

  function put(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[y][z][x] = block;
    }
  }

  function get(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[y][z][x];
    }
    return null;
  }

  // Theme palette extraction & fallbacks
  const stonePrimary = api.theme?.stone?.primary || "minecraft:quartz_block";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:quartz_pillar";
  const stoneStairs = api.theme?.stone?.stairs || "minecraft:quartz_stairs";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:quartz_slab";
  const stoneWall = api.theme?.stone?.wall || "minecraft:diorite_wall";
  const plinth = api.theme?.ground?.plinth || "minecraft:quartz_bricks";
  const pavement = api.theme?.ground?.pavement || "minecraft:smooth_quartz";

  // Arcane & Crystal palette
  const amethyst = "minecraft:amethyst_block";
  const budding = "minecraft:budding_amethyst";
  const purpur = "minecraft:purpur_block";
  const purpurPillar = "minecraft:purpur_pillar";
  const purpurStairs = "minecraft:purpur_stairs";
  const purpurSlab = "minecraft:purpur_slab";
  const lantern = "minecraft:sea_lantern";
  const endRod = "minecraft:end_rod";
  const tintedGlass = "minecraft:tinted_glass";

  // Block state helper functions
  function makeStair(baseString, facing, half = "bottom") {
    const name = (baseString || "minecraft:quartz_stairs").split("[")[0];
    return `${name}[facing=${facing},half=${half}]`;
  }

  function makeSlab(baseString, type = "bottom") {
    const name = (baseString || "minecraft:quartz_slab").split("[")[0];
    return `${name}[type=${type}]`;
  }

  function makeWall(baseString) {
    return (baseString || "minecraft:diorite_wall").split("[")[0];
  }

  // 1. TERRAIN CONFORMANCE & PEDESTAL FOUNDATION (Rule 6)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);

      // Footprint includes main octagonal dais plus the 4 entrance stair landings
      const inDais = dx <= 6 && dz <= 6 && dx + dz <= 9;
      const inNorthRamp = z <= 1 && dx <= 2;
      const inSouthRamp = z >= 15 && dx <= 2;
      const inEastRamp = x >= 15 && dz <= 2;
      const inWestRamp = x <= 1 && dz <= 2;

      if (inDais || inNorthRamp || inSouthRamp || inEastRamp || inWestRamp) {
        const rawH = api.heightAt(x, z);
        const groundY = Math.max(0, Math.min(seatY + 4, seatY + Math.round(rawH)));

        // Extend foundation down to terrain/seabed
        if (groundY < seatY) {
          for (let y = seatY - 1; y >= groundY; y--) {
            put(x, y, z, plinth);
          }
        } else if (groundY > seatY) {
          for (let y = seatY; y <= groundY; y++) {
            put(x, y, z, plinth);
          }
        }
      }
    }
  }

  // 2. DAIS FLOOR & INLAID ARCANE RUNES (y = seatY)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);

      if (dx <= 6 && dz <= 6 && dx + dz <= 9) {
        const isPerimeter = dx === 6 || dz === 6 || dx + dz === 9;

        if (isPerimeter) {
          put(x, seatY, z, plinth);
        } else if (dx === 0 && dz === 0) {
          put(x, seatY, z, lantern); // Central glowing nexus
        } else if (dx <= 1 && dz <= 1) {
          put(x, seatY, z, amethyst);
        } else if (dx === 0 || dz === 0) {
          put(x, seatY, z, purpur); // Cardinal warding lines
        } else if (dx === dz) {
          put(x, seatY, z, stoneAccent); // Diagonal quartz conduits
        } else {
          put(x, seatY, z, pavement);
        }
      }
    }
  }

  // Four grand entry stair ramps
  for (let offset = -1; offset <= 1; offset++) {
    // North entrance (towards front)
    put(cx + offset, seatY, 1, makeStair(stoneStairs, "south", "bottom"));
    put(cx + offset, seatY - 1, 0, makeStair(stoneStairs, "south", "bottom"));

    // South entrance
    put(cx + offset, seatY, 15, makeStair(stoneStairs, "north", "bottom"));
    put(cx + offset, seatY - 1, 16, makeStair(stoneStairs, "north", "bottom"));

    // East entrance
    put(15, seatY, cz + offset, makeStair(stoneStairs, "west", "bottom"));
    put(16, seatY - 1, cz + offset, makeStair(stoneStairs, "west", "bottom"));

    // West entrance
    put(1, seatY, cz + offset, makeStair(stoneStairs, "east", "bottom"));
    put(0, seatY - 1, cz + offset, makeStair(stoneStairs, "east", "bottom"));
  }

  // Inner Sanctuary Tier (seatY + 1)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);

      if (dx <= 5 && dz <= 5 && dx + dz <= 7) {
        // Keep cardinal walkways completely open for entry
        const isAisle = (dx <= 1 && dz >= 2) || (dz <= 1 && dx >= 2);

        if (isAisle) {
          put(x, seatY + 1, z, pavement);
        } else if (dx === 0 && dz === 0) {
          put(x, seatY + 1, z, lantern);
        } else if (dx <= 1 && dz <= 1) {
          put(x, seatY + 1, z, purpur);
        } else if (dx + dz === 6 || dx + dz === 7) {
          put(x, seatY + 1, z, stonePrimary);
        } else {
          put(x, seatY + 1, z, pavement);
        }
      }
    }
  }

  // 3. FOUR CARDINAL ENTRANCE PORTAL ARCHES (seatY + 1 to seatY + 8)
  const portals = [
    { name: "north", sx: 0, sz: -1, pier1: [5, 3], pier2: [11, 3], wallFacing: "south" },
    { name: "south", sx: 0, sz: 1, pier1: [5, 13], pier2: [11, 13], wallFacing: "north" },
    { name: "west", sx: -1, sz: 0, pier1: [3, 5], pier2: [3, 11], wallFacing: "east" },
    { name: "east", sx: 1, sz: 0, pier1: [13, 5], pier2: [13, 11], wallFacing: "west" },
  ];

  for (const portal of portals) {
    const isNS = portal.name === "north" || portal.name === "south";
    const pz = portal.name === "north" ? 3 : portal.name === "south" ? 13 : cz;
    const px = portal.name === "west" ? 3 : portal.name === "east" ? 13 : cx;

    if (isNS) {
      // Upright piers
      for (let y = seatY + 1; y <= seatY + 5; y++) {
        put(cx - 3, y, pz, stoneAccent);
        put(cx + 3, y, pz, stoneAccent);
        put(cx - 3, y, pz + (portal.name === "north" ? 1 : -1), stonePrimary);
        put(cx + 3, y, pz + (portal.name === "north" ? 1 : -1), stonePrimary);
      }
      // Arch springing & keystone
      put(cx - 3, seatY + 6, pz, makeStair(stoneStairs, "east", "top"));
      put(cx - 2, seatY + 6, pz, makeStair(stoneStairs, "east", "bottom"));
      put(cx - 1, seatY + 7, pz, makeStair(stoneStairs, "east", "top"));
      put(cx, seatY + 7, pz, stonePrimary);
      put(cx, seatY + 8, pz, makeSlab(stoneSlab, "bottom"));
      put(cx + 1, seatY + 7, pz, makeStair(stoneStairs, "west", "top"));
      put(cx + 2, seatY + 6, pz, makeStair(stoneStairs, "west", "bottom"));
      put(cx + 3, seatY + 6, pz, makeStair(stoneStairs, "west", "top"));
    } else {
      // East-West Upright piers
      for (let y = seatY + 1; y <= seatY + 5; y++) {
        put(px, y, cz - 3, stoneAccent);
        put(px, y, cz + 3, stoneAccent);
        put(px + (portal.name === "west" ? 1 : -1), y, cz - 3, stonePrimary);
        put(px + (portal.name === "west" ? 1 : -1), y, cz + 3, stonePrimary);
      }
      // Arch springing & keystone
      put(px, seatY + 6, cz - 3, makeStair(stoneStairs, "south", "top"));
      put(px, seatY + 6, cz - 2, makeStair(stoneStairs, "south", "bottom"));
      put(px, seatY + 7, cz - 1, makeStair(stoneStairs, "south", "top"));
      put(px, seatY + 7, cz, stonePrimary);
      put(px, seatY + 8, cz, makeSlab(stoneSlab, "bottom"));
      put(px, seatY + 7, cz + 1, makeStair(stoneStairs, "north", "top"));
      put(px, seatY + 6, cz + 2, makeStair(stoneStairs, "north", "bottom"));
      put(px, seatY + 6, cz + 3, makeStair(stoneStairs, "north", "top"));
    }
  }

  // 4. FOUR SOARING QUARTZ BUTTRESS PYLONS (seatY + 1 to seatY + 38)
  const cornerSigns = [
    [-1, -1],
    [1, -1],
    [-1, 1],
    [1, 1],
  ];

  for (const [sx, sz] of cornerSigns) {
    for (let yrel = 1; yrel <= 38; yrel++) {
      const iy = seatY + yrel;
      const t = yrel / 38;

      // Smooth parabolic gothic curve curving inward
      const radius = 5.5 * Math.pow(1 - 0.62 * t, 1.35) + 0.6;
      const ix = Math.round(cx + sx * radius);
      const iz = Math.round(cz + sz * radius);

      // Core rib
      put(ix, iy, iz, stonePrimary);

      // Pylon fluting & structural bracing
      if (yrel <= 6) {
        // Broad lower buttress base
        put(ix - sx, iy, iz, stoneAccent);
        put(ix, iy, iz - sz, stoneAccent);
        put(ix + sx, iy, iz, makeStair(stoneStairs, sx > 0 ? "west" : "east", "bottom"));
        put(ix, iy, iz + sz, makeStair(stoneStairs, sz > 0 ? "north" : "south", "bottom"));
        put(ix + sx, iy, iz + sz, makeWall(stoneWall));
      } else if (yrel <= 24) {
        // Mid-height soaring spine
        put(ix - sx, iy, iz, stoneAccent);
        put(ix, iy, iz - sz, stoneAccent);
        put(ix + sx, iy, iz + sz, makeWall(stoneWall));

        // Embedded mana nodes
        if (yrel === 12 || yrel === 20) {
          put(ix, iy, iz, lantern);
          put(ix - sx, iy, iz, purpur);
        }
      } else if (yrel <= 33) {
        // Upper converging rib
        put(ix - sx, iy, iz, purpur);
        put(ix, iy, iz - sz, purpur);
        put(ix, iy, iz, stoneAccent);
      } else if (yrel <= 37) {
        // Crown pinnacle prongs
        put(ix, iy, iz, makeWall(stoneWall));
      } else if (yrel === 38) {
        // Glowing celestial finial tip
        put(ix, iy, iz, "minecraft:end_rod[facing=up]");
      }
    }
  }

  // 5. ARCANE RESONANCE RINGS & FLYING ARCH BRACES
  // Lower Flying Braces (yrel = 14)
  for (const [sx, sz] of cornerSigns) {
    const iy = seatY + 14;
    put(cx + sx * 2, iy, cz + sz * 2, purpur);
    put(cx + sx * 3, iy, cz + sz * 3, makeSlab(purpurSlab, "top"));
    put(cx + sx * 4, iy, cz + sz * 4, stonePrimary);
  }

  // Mid Energy Ring & Satellite Floating Shards (yrel = 24 to 26)
  const ringY = seatY + 25;
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);
      const dist = Math.hypot(dx, dz);

      if (dist >= 2.6 && dist <= 3.6 && !(dx === 3 && dz === 3)) {
        put(x, ringY, z, purpur);
        if ((dx === 3 && dz === 0) || (dx === 0 && dz === 3)) {
          // Cardinal orbiting crystal focus nodes
          put(x, ringY - 1, z, makeStair(purpurStairs, dz === 3 ? (z > cz ? "north" : "south") : (x > cx ? "west" : "east"), "top"));
          put(x, ringY, z, lantern);
          put(x, ringY + 1, z, budding);
          put(x, ringY + 2, z, "minecraft:end_rod[facing=up]");
        }
      }
    }
  }

  // Upper Celestial Crown (yrel = 33 to 35)
  const crownY = seatY + 34;
  for (let x = cx - 2; x <= cx + 2; x++) {
    for (let z = cz - 2; z <= cz + 2; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);

      if (dx <= 2 && dz <= 2 && !(dx === 2 && dz === 2)) {
        put(x, crownY - 1, z, stoneAccent);
        put(x, crownY, z, (dx === 2 || dz === 2) ? lantern : purpur);
        put(x, crownY + 1, z, makeSlab(stoneSlab, "bottom"));
      }
    }
  }

  // 6. THE ARCANE CRYSTAL SPIRE CORE (seatY + 2 to seatY + 44)
  // Section A: Sanctuary Pool & Crystal Anchor (yrel = 2 to 5)
  put(cx, seatY + 2, cz, lantern);
  put(cx, seatY + 3, cz, budding);
  put(cx, seatY + 4, cz, amethyst);
  put(cx, seatY + 5, cz, budding);

  for (const [ox, oz] of [[0, 1], [0, -1], [1, 0], [-1, 0]]) {
    put(cx + ox, seatY + 2, cz + oz, purpurPillar);
    put(cx + ox, seatY + 3, cz + oz, amethyst);
    put(cx + ox, seatY + 4, cz + oz, amethyst);
    put(cx + ox, seatY + 5, cz + oz, purpurPillar);
  }

  // Section B: Lower Crystal Node (yrel = 6 to 12)
  const lowerRadii = [1.2, 1.6, 2.1, 2.4, 2.0, 1.5, 1.2]; // yrel 6..12
  for (let idx = 0; idx < lowerRadii.length; idx++) {
    const yrel = 6 + idx;
    const iy = seatY + yrel;
    const r = lowerRadii[idx];

    for (let x = cx - 3; x <= cx + 3; x++) {
      for (let z = cz - 3; z <= cz + 3; z++) {
        const dx = Math.abs(x - cx);
        const dz = Math.abs(z - cz);
        const d = Math.hypot(dx, dz);

        if (d <= r) {
          if (d <= 0.7) {
            put(x, iy, z, yrel % 2 === 1 ? lantern : budding);
          } else if (d <= r - 0.5) {
            put(x, iy, z, amethyst);
          } else {
            put(x, iy, z, (x + z + yrel) % 2 === 0 ? amethyst : purpur);
          }
        }
      }
    }
  }

  // Section C: Lower Waist (yrel = 13 to 15)
  for (let yrel = 13; yrel <= 15; yrel++) {
    const iy = seatY + yrel;
    put(cx, iy, cz, yrel === 14 ? lantern : budding);
    for (const [ox, oz] of [[0, 1], [0, -1], [1, 0], [-1, 0]]) {
      put(cx + ox, iy, cz + oz, purpurPillar);
    }
  }

  // Section D: The Great Celestial Crystal Heart (yrel = 16 to 27)
  const heartRadii = [
    1.4, // 16
    1.9, // 17
    2.4, // 18
    2.8, // 19
    3.1, // 20
    3.3, // 21 (Equator)
    3.2, // 22
    2.9, // 23
    2.4, // 24
    1.9, // 25
    1.5, // 26
    1.2, // 27
  ];

  for (let idx = 0; idx < heartRadii.length; idx++) {
    const yrel = 16 + idx;
    const iy = seatY + yrel;
    const r = heartRadii[idx];

    for (let x = cx - 4; x <= cx + 4; x++) {
      for (let z = cz - 4; z <= cz + 4; z++) {
        const dx = Math.abs(x - cx);
        const dz = Math.abs(z - cz);
        const d = Math.hypot(dx, dz);

        if (dx <= r && dz <= r && dx + dz <= r * 1.35) {
          if (d <= 0.8) {
            // Radiant core pulses
            put(x, iy, z, yrel === 21 || yrel === 19 || yrel === 23 ? lantern : budding);
          } else if (d <= r - 0.7) {
            put(x, iy, z, amethyst);
          } else {
            // Faceted crystal exterior
            if ((x + z + yrel) % 3 === 0) {
              put(x, iy, z, tintedGlass);
            } else if ((x + z) % 2 === 0) {
              put(x, iy, z, amethyst);
            } else {
              put(x, iy, z, purpur);
            }
          }
        }
      }
    }
  }

  // Radiating outward crystal clusters at the equator (yrel = 21)
  put(cx + 3, seatY + 21, cz, "minecraft:amethyst_cluster[facing=east]");
  put(cx - 3, seatY + 21, cz, "minecraft:amethyst_cluster[facing=west]");
  put(cx, seatY + 21, cz + 3, "minecraft:amethyst_cluster[facing=south]");
  put(cx, seatY + 21, cz - 3, "minecraft:amethyst_cluster[facing=north]");

  // Section E: Upper Crystal Spire Shaft (yrel = 28 to 33)
  for (let yrel = 28; yrel <= 33; yrel++) {
    const iy = seatY + yrel;
    put(cx, iy, cz, yrel === 30 ? lantern : budding);

    const crossR = yrel <= 30 ? 1.4 : 1.0;
    for (const [ox, oz] of [[0, 1], [0, -1], [1, 0], [-1, 0]]) {
      put(cx + ox, iy, cz + oz, yrel % 2 === 0 ? purpurPillar : amethyst);
    }
    if (crossR > 1.2) {
      for (const [ox, oz] of [[1, 1], [-1, 1], [1, -1], [-1, -1]]) {
        put(cx + ox, iy, cz + oz, amethyst);
      }
    }
  }

  // Section F: The Celestial Apex Needle (yrel = 34 to 44)
  put(cx, seatY + 34, cz, lantern);
  put(cx, seatY + 35, cz, amethyst);
  put(cx, seatY + 36, cz, purpurPillar);
  put(cx, seatY + 37, cz, budding);
  put(cx, seatY + 38, cz, lantern);
  put(cx, seatY + 39, cz, amethyst);
  put(cx, seatY + 40, cz, purpurPillar);
  put(cx, seatY + 41, cz, budding);
  put(cx, seatY + 42, cz, amethyst);
  put(cx, seatY + 43, cz, "minecraft:end_rod[facing=up]");
  put(cx, seatY + 44, cz, "minecraft:end_rod[facing=up]"); // Piercing celestial beacon

  // Cross braces supporting the needle at yrel = 35..37
  for (const [ox, oz] of [[0, 1], [0, -1], [1, 0], [-1, 0]]) {
    put(cx + ox, seatY + 35, cz + oz, amethyst);
    put(cx + ox, seatY + 36, cz + oz, makeWall(stoneWall));
  }

  // 7. FLUSH GRID TO WORLD DETERMINISTICALLY (Rule 1 & Rule 8)
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const block = grid[y][z][x];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Celestial Crystal Spire",
    seatY: seatY,
    anchors: {
      front: [cx, seatY + 1, 0],
      door: [cx, seatY + 1, 2],
      focus: [cx, seatY + 2, cz],
      heart: [cx, seatY + 21, cz],
      apex: [cx, seatY + 44, cz],
    },
    interiors: [
      {
        min: [5, seatY + 1, 5],
        max: [11, seatY + 7, 11],
        kind: "vault",
      },
    ],
  };
}

