export const envelope = [11, 12, 11];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 3;
  const DECK_Y = seatY + 1; // Y = 4: Gun platform deck
  const inst = api.instance.index;

  // Palette resolution with robust fallbacks
  const tWood = api.theme.wood;
  const tStone = api.theme.stone;
  const tGround = api.theme.ground;

  const woodPlanks = tWood.planks || "minecraft:dark_oak_planks";
  const woodLog = tWood.log || "minecraft:dark_oak_log";
  const woodStripped = tWood.stripped || "minecraft:stripped_dark_oak_log";
  const woodStairs = tWood.stairs || "minecraft:dark_oak_stairs";
  const woodSlab = tWood.slab || "minecraft:dark_oak_slab";
  const woodFence = tWood.fence || "minecraft:dark_oak_fence";
  const woodTrapdoor = tWood.trapdoor || "minecraft:dark_oak_trapdoor";

  const stonePrimary = tStone.primary || "minecraft:cobblestone";
  const stoneAccent = tStone.accent || "minecraft:mossy_cobblestone";
  const stoneStairs = tStone.stairs || "minecraft:cobblestone_stairs";
  const stoneSlab = tStone.slab || "minecraft:cobblestone_slab";
  const stoneWall = tStone.wall || "minecraft:cobblestone_wall";

  const groundRevetment = tGround.revetment || "minecraft:mud_bricks";
  const groundPlinth = tGround.plinth || "minecraft:deepslate_bricks";

  function withState(block, state) {
    if (!block) return state;
    const base = block.split("[")[0];
    return `${base}[${state}]`;
  }

  // 3D Voxel buffer for atomic writes and connectivity
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  function setBlock(x, y, z, blockStr) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = blockStr;
    }
  }

  // Instance variation flags
  const leftRecoil = inst % 2 === 0;
  const rightRecoil = inst % 3 === 1;
  const leftElevated = inst % 3 === 2;
  const isFiring = inst === 1 || inst === 4;
  const mastSide = inst % 2 === 0 ? 8 : 2;
  const unicornStrike = inst % 2 === 1;
  const battleDamage = inst % 3 === 0;

  // 1. FOOTPRINT DEFINITION
  function isFootprint(x, z) {
    if (x >= 1 && x <= 9 && z >= 1 && z <= 9) return true;
    if (z === 0 && (x === 1 || x === 3 || x === 5 || x === 7 || x === 9)) return true;
    if (z === 10 && x >= 3 && x <= 7) return true;
    if ((x === 0 || x === 10) && z >= 1 && z <= 9) return true;
    return false;
  }

  // 2. TERRAIN CONFORMANCE & FOUNDATION PILES
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (!isFootprint(x, z)) continue;

      const rawH = api.heightAt(x, z);
      const groundY = Math.max(0, Math.min(DECK_Y, seatY + Math.floor(rawH)));

      // Build foundation column from ground up to deck base
      for (let y = groundY; y < DECK_Y; y++) {
        const isCorner = (x === 1 || x === 9) && (z === 1 || z === 9);
        const isOuter = x === 1 || x === 9 || z === 1 || z === 9;

        if (isCorner) {
          setBlock(x, y, z, withState(woodLog, "axis=y"));
        } else if (isOuter) {
          if (y === groundY) {
            setBlock(x, y, z, groundPlinth);
          } else if ((x + y + z) % 2 === 0) {
            setBlock(x, y, z, stonePrimary);
          } else {
            setBlock(x, y, z, groundRevetment);
          }
        } else {
          // Interior heavy timber framing
          if (x === 3 || x === 5 || x === 7 || z === 3 || z === 6) {
            setBlock(x, y, z, withState(woodLog, "axis=y"));
          } else {
            setBlock(x, y, z, woodPlanks);
          }
        }
      }

      // External buttress stilts
      if (x === 0 || x === 10 || (z === 0 && (x === 1 || x === 5 || x === 9))) {
        for (let y = groundY; y < DECK_Y; y++) {
          setBlock(x, y, z, withState(woodLog, "axis=y"));
        }
      }
    }
  }

  // 3. FORTIFIED GUN DECK FLOOR (Y = 4)
  for (let x = 1; x <= 9; x++) {
    for (let z = 2; z <= 8; z++) {
      if (x === 5) {
        // Central reinforced spine
        setBlock(x, DECK_Y, z, withState(woodStripped, "axis=z"));
      } else if (x === 2 || x === 4 || x === 6 || x === 8) {
        // Recoil runners for the heavy carriages
        setBlock(x, DECK_Y, z, withState(woodStripped, "axis=z"));
      } else {
        setBlock(x, DECK_Y, z, woodPlanks);
      }
    }
  }

  // Drainage & smoke vent grate in deck center
  setBlock(5, DECK_Y, 4, "minecraft:iron_bars");

  // 4. FRONT BREASTWORK & CANNON EMBRASURES (Z = 1, Y = 5..7)
  for (let x = 1; x <= 9; x++) {
    // Parapet Base (Y = 5)
    if (x === 1 || x === 9) {
      setBlock(x, 5, 1, withState(woodLog, "axis=y"));
    } else if (x === 5) {
      setBlock(x, 5, 1, groundRevetment);
    } else if (x === 2 || x === 6) {
      setBlock(x, 5, 1, withState(woodStairs, "facing=east,half=bottom"));
    } else if (x === 4 || x === 8) {
      setBlock(x, 5, 1, withState(woodStairs, "facing=west,half=bottom"));
    } else if (x === 3 || x === 7) {
      // Gun port sill
      setBlock(x, 5, 1, withState(stoneSlab, "type=bottom"));
    }

    // Parapet Wall (Y = 6)
    if (x === 1 || x === 9) {
      setBlock(x, 6, 1, "minecraft:mud_bricks");
    } else if (x === 5) {
      setBlock(x, 6, 1, "minecraft:packed_mud");
    } else if (x === 2 || x === 6) {
      setBlock(x, 6, 1, withState(woodStairs, "facing=east,half=bottom"));
    } else if (x === 4 || x === 8) {
      setBlock(x, 6, 1, withState(woodStairs, "facing=west,half=bottom"));
    }

    // Sandbag & Timber Coping (Y = 7)
    if (x === 1 || x === 9) {
      setBlock(x, 7, 1, withState(woodTrapdoor, "facing=north,half=bottom,open=false"));
    } else if (x === 2 || x === 4 || x === 5 || x === 6 || x === 8) {
      setBlock(x, 7, 1, "minecraft:mud_brick_slab[type=bottom]");
    }
  }

  // Front Apron Sandbag Bundles (Z = 0)
  setBlock(1, 4, 0, withState(woodStairs, "facing=south,half=bottom"));
  setBlock(5, 4, 0, "minecraft:mud_brick_stairs[facing=south,half=bottom]");
  setBlock(9, 4, 0, withState(woodStairs, "facing=south,half=bottom"));
  setBlock(5, 5, 0, withState(woodTrapdoor, "facing=north,half=bottom,open=false"));

  // 5. FLANK WALLS & REAR PARAPETS (X = 1 & X = 9, Z = 2..8)
  for (let z = 2; z <= 8; z++) {
    // West Wall (X = 1)
    if (z % 2 === 0) {
      setBlock(1, 5, z, withState(woodLog, "axis=y"));
      setBlock(1, 6, z, "minecraft:mud_brick_wall");
      setBlock(0, 5, z, withState(woodStairs, "facing=east,half=bottom"));
    } else {
      setBlock(1, 5, z, groundRevetment);
      setBlock(1, 6, z, woodFence);
    }

    // East Wall (X = 9)
    if (z % 2 === 0) {
      setBlock(9, 5, z, withState(woodLog, "axis=y"));
      setBlock(9, 6, z, "minecraft:mud_brick_wall");
      setBlock(10, 5, z, withState(woodStairs, "facing=west,half=bottom"));
    } else {
      setBlock(9, 5, z, groundRevetment);
      setBlock(9, 6, z, woodFence);
    }
  }

  // 6. SOUTH REAR WALL & ENTRANCE STAIRS (Z = 8..10)
  // Rear breastworks flanking the entrance
  setBlock(2, 5, 8, groundRevetment);
  setBlock(3, 5, 8, groundRevetment);
  setBlock(2, 6, 8, woodFence);
  setBlock(3, 6, 8, woodFence);

  setBlock(7, 5, 8, groundRevetment);
  setBlock(8, 5, 8, groundRevetment);
  setBlock(7, 6, 8, woodFence);
  setBlock(8, 6, 8, woodFence);

  // Staircase ascending to gun deck
  for (let x = 4; x <= 6; x++) {
    setBlock(x, 4, 9, withState(woodStairs, "facing=south,half=bottom"));
    setBlock(x, 3, 10, withState(woodStairs, "facing=south,half=bottom"));
  }
  setBlock(3, 5, 9, woodFence);
  setBlock(7, 5, 9, woodFence);

  // 7. TWIN HEAVY IRON CANNONS (Left: X = 3, Right: X = 7)
  function buildCannon(cx, isRecoil, elevated, firing) {
    const zBase = isRecoil ? 3 : 2;

    // Heavy carriage cheeks & axle (Y = 4 & 5)
    setBlock(cx - 1, 4, zBase, withState(woodStairs, "facing=east,half=bottom"));
    setBlock(cx + 1, 4, zBase, withState(woodStairs, "facing=west,half=bottom"));
    setBlock(cx - 1, 4, zBase + 1, withState(woodStairs, "facing=east,half=bottom"));
    setBlock(cx + 1, 4, zBase + 1, withState(woodStairs, "facing=west,half=bottom"));
    setBlock(cx, 4, zBase + 2, withState(woodStairs, "facing=north,half=bottom")); // carriage trail

    // Heavy iron trunnions & carriage bed
    setBlock(cx, 4, zBase + 1, withState(woodStripped, "axis=x"));

    // Cannon Barrel (Y = 5, or Y = 6 if elevated)
    const by = elevated ? 6 : 5;

    // Cascabel & Breech
    setBlock(cx, 5, zBase + 2, "minecraft:hopper[facing=north]");
    setBlock(
      cx,
      5,
      zBase + 1,
      firing
        ? "minecraft:blast_furnace[facing=north,lit=true]"
        : "minecraft:blast_furnace[facing=north,lit=false]"
    );

    // Chase & Muzzle protruding through the embrasure
    if (elevated) {
      setBlock(cx, 6, zBase, "minecraft:polished_basalt[axis=z]");
      setBlock(cx, 6, zBase - 1, "minecraft:dispenser[facing=north]");
      setBlock(cx, 5, zBase, withState(stoneSlab, "type=bottom")); // wedge
    } else {
      setBlock(cx, 5, zBase, "minecraft:polished_basalt[axis=z]");
      setBlock(cx, 5, zBase - 1, "minecraft:polished_basalt[axis=z]");
      if (!isRecoil) {
        setBlock(cx, 5, 0, "minecraft:dispenser[facing=north]");
      }
    }

    // Top carriage iron strap / fuse
    setBlock(cx, by + 1, zBase + 1, "minecraft:candle[lit=true]");

    // Firing flash / smoke effects
    if (firing) {
      setBlock(cx, 5, 0, "minecraft:cobweb");
      setBlock(cx, 6, 0, "minecraft:cobweb");
    }

    // Reloading tools when gun is recoiled
    if (isRecoil) {
      setBlock(cx - 1, 5, zBase, woodFence);
      setBlock(cx - 1, 6, zBase, "minecraft:sponge"); // rammer swab
    }
  }

  buildCannon(3, leftRecoil, leftElevated, isFiring && inst === 4);
  buildCannon(7, rightRecoil, false, isFiring && inst === 1);

  // 8. AMMUNITION CACHE & POWDER BARRELS
  if (mastSide === 8) {
    // Powder store on West flank
    setBlock(2, 5, 6, "minecraft:tnt");
    setBlock(2, 5, 7, "minecraft:barrel[facing=up]");
    setBlock(3, 5, 7, "minecraft:barrel[facing=north]");
    setBlock(2, 6, 7, "minecraft:barrel[facing=up]");
    setBlock(1, 5, 6, withState(woodTrapdoor, "facing=east,half=bottom,open=true"));

    // Cannonball pyramids on East flank
    setBlock(6, 5, 5, "minecraft:wither_skeleton_skull[rotation=0]");
    setBlock(6, 5, 6, "minecraft:wither_skeleton_skull[rotation=2]");
    setBlock(8, 5, 5, "minecraft:chest[facing=west]");
    setBlock(8, 5, 6, "minecraft:barrel[facing=east]");
    setBlock(8, 6, 6, "minecraft:flower_pot"); // grog mug
  } else {
    // Powder store on East flank
    setBlock(8, 5, 6, "minecraft:tnt");
    setBlock(8, 5, 7, "minecraft:barrel[facing=up]");
    setBlock(7, 5, 7, "minecraft:barrel[facing=north]");
    setBlock(8, 6, 7, "minecraft:barrel[facing=up]");
    setBlock(9, 5, 6, withState(woodTrapdoor, "facing=west,half=bottom,open=true"));

    // Cannonball pyramids on West flank
    setBlock(4, 5, 5, "minecraft:wither_skeleton_skull[rotation=0]");
    setBlock(4, 5, 6, "minecraft:wither_skeleton_skull[rotation=2]");
    setBlock(2, 5, 5, "minecraft:chest[facing=east]");
    setBlock(2, 5, 6, "minecraft:barrel[facing=west]");
    setBlock(2, 6, 6, "minecraft:candle[lit=true]");
  }

  // Artillery swab water cauldron (for extinguishing powder embers)
  setBlock(5, 5, 3, "minecraft:water_cauldron[level=3]");

  // 9. SIGNAL MAST & PIRATE SKULL STANDARD (Reaching Y = 10)
  const mx = mastSide;
  const mz = 7;

  // Sturdy mast base
  setBlock(mx, 5, mz, withState(woodLog, "axis=y"));
  setBlock(mx, 6, mz, withState(woodLog, "axis=y"));
  setBlock(mx, 7, mz, withState(woodLog, "axis=y"));
  setBlock(mx, 8, mz, woodFence);
  setBlock(mx, 9, mz, woodFence);

  // Yardarm / Cross Spar (Y = 9)
  setBlock(mx - 1, 9, mz, woodFence);
  setBlock(mx + 1, 9, mz, woodFence);

  // Tattered Pirate Flag / Black Sails
  setBlock(mx - 1, 8, mz, "minecraft:black_wool");
  setBlock(mx, 8, mz, "minecraft:skeleton_skull[rotation=0]");
  setBlock(mx + 1, 8, mz, "minecraft:black_wool");
  setBlock(mx - 1, 7, mz, "minecraft:black_wool");
  setBlock(mx + 1, 7, mz, "minecraft:black_wool");

  // Mast Top Skull & Signal Lantern
  setBlock(mx, 10, mz, "minecraft:skeleton_skull[rotation=0]");
  setBlock(mx + 1, 8, mz + 1, "minecraft:chain[axis=y]");
  setBlock(mx + 1, 7, mz + 1, "minecraft:lantern[hanging=true]");

  // 10. WAR DETAILS: SKULL TROPHIES & UNICORN SIEGE DAMAGE
  // Skull posts on front merlons
  setBlock(1, 7, 1, "minecraft:skeleton_skull[rotation=4]");
  setBlock(9, 7, 1, "minecraft:skeleton_skull[rotation=12]");
  setBlock(5, 7, 1, woodFence);
  setBlock(5, 8, 1, "minecraft:skeleton_skull[rotation=0]");

  // Magical retaliation crystal arrow from unicorn isle bastion
  if (unicornStrike) {
    setBlock(2, 6, 1, "minecraft:amethyst_cluster[facing=south]");
    setBlock(5, 6, 2, "minecraft:glowstone");
  }

  // Battle splintering / scorch damage
  if (battleDamage) {
    setBlock(1, 5, 4, "minecraft:basalt[axis=y]");
    setBlock(0, 5, 4, "minecraft:coal_block");
  }

  // 11. COMMIT TO API
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const blk = grid[x][y][z];
        if (blk !== null) {
          api.set(x, y, z, blk);
        }
      }
    }
  }

  return {
    name: "pirate_cannon_battery",
    seatY: seatY,
    anchors: {
      front: [5, DECK_Y, 0],
      entrance: [5, seatY, 10],
      deck: [5, DECK_Y, 5],
    },
  };
}

warding_crystal_pylon.source:
export const envelope = [9, 19, 9];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 5;
  const cx = 4;
  const cz = 4;

  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => Array(D).fill(null))
  );

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  function getBlock(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[x][y][z];
    }
    return null;
  }

  function placeCluster(x, y, z, facing, type = "minecraft:amethyst_cluster") {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    if (grid[x][y][z] !== null) return;

    let sx = x, sy = y, sz = z;
    if (facing === "up") sy = y - 1;
    else if (facing === "down") sy = y + 1;
    else if (facing === "north") sz = z + 1;
    else if (facing === "south") sz = z - 1;
    else if (facing === "east") sx = x - 1;
    else if (facing === "west") sx = x + 1;

    if (sx >= 0 && sx < W && sy >= 0 && sy < H && sz >= 0 && sz < D) {
      if (grid[sx][sy][sz] !== null) {
        grid[x][y][z] = `${type}[facing=${facing}]`;
      }
    }
  }

  const t = api.theme;
  const stonePrimary = (t.stone && t.stone.primary) || "minecraft:quartz_block";
  const stoneAccent = (t.stone && t.stone.accent) || "minecraft:smooth_quartz";
  const stoneStairs = (t.stone && t.stone.stairs) || "minecraft:quartz_stairs";
  const stoneSlab = (t.stone && t.stone.slab) || "minecraft:quartz_slab";
  const stoneWall = (t.stone && t.stone.wall) || "minecraft:diorite_wall";
  const plinth = (t.ground && t.ground.plinth) || stonePrimary;
  const pavement = (t.ground && t.ground.pavement) || stoneAccent;

  function stairs(base, facing, half = "bottom") {
    const id = base.split("[")[0];
    return `${id}[facing=${facing},half=${half}]`;
  }

  function slab(base, type = "bottom") {
    const id = base.split("[")[0];
    return `${id}[type=${type}]`;
  }

  function wall(base) {
    return base.split("[")[0];
  }

  const baseDeckY = seatY + 1; // y = 6

  // 1. Foundation & Skirt conforming to ground
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);
      const inFootprint = (dx <= 4 && dz <= 4 && (dx + dz <= 6));
      if (!inFootprint) continue;

      const h = api.heightAt(x, z);
      const groundY = Math.max(0, Math.min(H - 1, Math.round(seatY + h)));
      const minY = Math.min(groundY, baseDeckY);
      const maxY = Math.max(groundY, baseDeckY);
      const isOuter = (dx === 4 || dz === 4 || (dx + dz === 6));

      for (let y = minY; y <= maxY; y++) {
        let block;
        if (y === baseDeckY) {
          block = isOuter ? pavement : stoneAccent;
        } else if (isOuter) {
          block = plinth;
        } else {
          block = (api.random() < 0.15) ? "minecraft:quartz_bricks" : stonePrimary;
        }
        setBlock(x, y, z, block);
      }
    }
  }

  // 2. Pedestal Tier 1 (y = 7)
  for (let x = 1; x <= 7; x++) {
    for (let z = 1; z <= 7; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);
      if (dx <= 3 && dz <= 3 && (dx + dz <= 4)) {
        if (dx === 3 && dz === 0) {
          setBlock(x, 7, z, stairs(stoneStairs, x < cx ? "west" : "east"));
        } else if (dz === 3 && dx === 0) {
          setBlock(x, 7, z, stairs(stoneStairs, z < cz ? "north" : "south"));
        } else if (dx === 2 && dz === 2) {
          setBlock(x, 7, z, slab(stoneSlab, "bottom"));
        } else {
          setBlock(x, 7, z, (dx + dz === 3) ? stoneAccent : "minecraft:quartz_bricks");
        }
      }
    }
  }

  // 3. Pedestal Tier 2 (y = 8)
  for (let x = 2; x <= 6; x++) {
    for (let z = 2; z <= 6; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);
      if (dx <= 2 && dz <= 2) {
        if (dx === 2 && dz === 2) {
          setBlock(x, 8, z, "minecraft:chiseled_quartz_block");
        } else if (dx === 2 && dz === 0) {
          setBlock(x, 8, z, stairs(stoneStairs, x < cx ? "west" : "east"));
        } else if (dz === 2 && dx === 0) {
          setBlock(x, 8, z, stairs(stoneStairs, z < cz ? "north" : "south"));
        } else if (dx === 0 && dz === 0) {
          setBlock(x, 8, z, "minecraft:sea_lantern");
        } else {
          setBlock(x, 8, z, stonePrimary);
        }
      }
    }
  }

  // Choose 1 of 6 distinct archetypes
  const variant = api.instance.index % 6;

  if (variant === 0) {
    // --- VARIANT 0: Luminescent Apex Ward ---
    // 4 Fluted pillars & corner walls
    for (let y = 9; y <= 13; y++) {
      setBlock(2, y, 4, y === 12 ? stairs(stoneStairs, "east", "top") : "minecraft:quartz_pillar[axis=y]");
      setBlock(6, y, 4, y === 12 ? stairs(stoneStairs, "west", "top") : "minecraft:quartz_pillar[axis=y]");
      setBlock(4, y, 2, y === 12 ? stairs(stoneStairs, "south", "top") : "minecraft:quartz_pillar[axis=y]");
      setBlock(4, y, 6, y === 12 ? stairs(stoneStairs, "north", "top") : "minecraft:quartz_pillar[axis=y]");

      if (y <= 11) {
        setBlock(2, y, 2, wall(stoneWall));
        setBlock(6, y, 2, wall(stoneWall));
        setBlock(2, y, 6, wall(stoneWall));
        setBlock(6, y, 6, wall(stoneWall));
      }
    }
    // Center glowing conduit
    setBlock(4, 9, 4, "minecraft:sea_lantern");
    setBlock(4, 10, 4, "minecraft:amethyst_block");
    setBlock(4, 11, 4, "minecraft:amethyst_block");
    setBlock(4, 12, 4, "minecraft:amethyst_block");
    setBlock(4, 13, 4, "minecraft:sea_lantern");

    // Ward focus plates
    for (let y = 10; y <= 12; y++) {
      setBlock(3, y, 3, "minecraft:tinted_glass");
      setBlock(5, y, 3, "minecraft:tinted_glass");
      setBlock(3, y, 5, "minecraft:tinted_glass");
      setBlock(5, y, 5, "minecraft:tinted_glass");
    }

    // Apex Crystal Spire
    for (let x = 3; x <= 5; x++) {
      for (let z = 3; z <= 5; z++) {
        setBlock(x, 14, z, (x === 4 && z === 4) ? "minecraft:amethyst_block" : slab(stoneSlab, "bottom"));
      }
    }
    setBlock(4, 15, 4, "minecraft:amethyst_block");
    setBlock(4, 15, 3, "minecraft:amethyst_block");
    setBlock(4, 15, 5, "minecraft:amethyst_block");
    setBlock(3, 15, 4, "minecraft:amethyst_block");
    setBlock(5, 15, 4, "minecraft:amethyst_block");

    setBlock(4, 16, 4, "minecraft:budding_amethyst");
    placeCluster(4, 16, 3, "north");
    placeCluster(4, 16, 5, "south");
    placeCluster(3, 16, 4, "west");
    placeCluster(5, 16, 4, "east");

    setBlock(4, 17, 4, "minecraft:amethyst_block");
    placeCluster(4, 18, 4, "up");
    placeCluster(4, 14, 2, "north");
    placeCluster(4, 14, 6, "south");
    placeCluster(2, 14, 4, "west");
    placeCluster(6, 14, 4, "east");

  } else if (variant === 1) {
    // --- VARIANT 1: Prismatic Font of Aegis ---
    // Chalice basin
    for (let x = 2; x <= 6; x++) {
      for (let z = 2; z <= 6; z++) {
        const dx = Math.abs(x - cx);
        const dz = Math.abs(z - cz);
        if (dx === 2 || dz === 2) {
          let f = "north";
          if (dz === 2 && z < cz) f = "south";
          else if (dz === 2 && z > cz) f = "north";
          else if (dx === 2 && x < cx) f = "east";
          else if (dx === 2 && x > cx) f = "west";
          setBlock(x, 9, z, stairs(stoneStairs, f, "top"));
        } else {
          setBlock(x, 9, z, (dx === 0 && dz === 0) ? "minecraft:sea_lantern" : "minecraft:crying_obsidian");
        }
      }
    }
    // Corner Chalice Buttresses
    for (let y = 8; y <= 10; y++) {
      setBlock(1, y, 1, wall(stoneWall));
      setBlock(7, y, 1, wall(stoneWall));
      setBlock(1, y, 7, wall(stoneWall));
      setBlock(7, y, 7, wall(stoneWall));
    }

    // Geode body
    for (let y = 10; y <= 13; y++) {
      for (let x = 3; x <= 5; x++) {
        for (let z = 3; z <= 5; z++) {
          if (x === 4 && z === 4 && (y === 11 || y === 12)) {
            setBlock(x, y, z, "minecraft:sea_lantern");
          } else {
            const b = (api.random() < 0.3) ? "minecraft:crying_obsidian" : "minecraft:amethyst_block";
            setBlock(x, y, z, b);
          }
        }
      }
    }

    // 4 Diagonal Crystal Horns
    const diagonals = [
      { x: 2, z: 2, fx: "west", fz: "north" },
      { x: 6, z: 2, fx: "east", fz: "north" },
      { x: 2, z: 6, fx: "west", fz: "south" },
      { x: 6, z: 6, fx: "east", fz: "south" },
    ];
    diagonals.forEach(d => {
      setBlock(d.x, 13, d.z, "minecraft:amethyst_block");
      setBlock(d.x, 14, d.z, "minecraft:budding_amethyst");
      placeCluster(d.x, 15, d.z, "up");
      placeCluster(d.x > cx ? d.x + 1 : d.x - 1, 14, d.z, d.fx);
      placeCluster(d.x, 14, d.z > cz ? d.z + 1 : d.z - 1, d.fz);
    });

    // Central Apex
    setBlock(4, 14, 4, "minecraft:sea_lantern");
    setBlock(4, 15, 4, "minecraft:amethyst_block");
    setBlock(4, 16, 4, "minecraft:budding_amethyst");
    placeCluster(4, 17, 4, "up");

  } else if (variant === 2) {
    // --- VARIANT 2: Twin-Crescent Starlight Bastion ---
    // Elongated dais & conduits
    setBlock(4, 9, 4, "minecraft:crying_obsidian");
    setBlock(4, 8, 2, stairs(stoneStairs, "south"));
    setBlock(4, 8, 6, stairs(stoneStairs, "north"));

    // West Horn
    setBlock(2, 9, 4, stonePrimary);
    setBlock(1, 9, 4, stairs(stoneStairs, "west"));
    for (let y = 10; y <= 11; y++) {
      setBlock(1, y, 4, "minecraft:quartz_pillar[axis=y]");
      setBlock(1, y, 3, wall(stoneWall));
      setBlock(1, y, 5, wall(stoneWall));
    }
    setBlock(1, 12, 4, stonePrimary);
    setBlock(2, 12, 4, stairs(stoneStairs, "west", "top"));
    setBlock(2, 13, 4, stonePrimary);
    setBlock(1, 13, 4, stairs(stoneStairs, "east"));
    setBlock(2, 14, 4, "minecraft:quartz_pillar[axis=y]");
    setBlock(3, 14, 4, stairs(stoneStairs, "west", "top"));
    setBlock(3, 15, 4, stonePrimary);
    setBlock(2, 15, 4, stairs(stoneStairs, "east"));
    setBlock(3, 16, 4, slab(stoneSlab, "bottom"));

    // East Horn
    setBlock(6, 9, 4, stonePrimary);
    setBlock(7, 9, 4, stairs(stoneStairs, "east"));
    for (let y = 10; y <= 11; y++) {
      setBlock(7, y, 4, "minecraft:quartz_pillar[axis=y]");
      setBlock(7, y, 3, wall(stoneWall));
      setBlock(7, y, 5, wall(stoneWall));
    }
    setBlock(7, 12, 4, stonePrimary);
    setBlock(6, 12, 4, stairs(stoneStairs, "east", "top"));
    setBlock(6, 13, 4, stonePrimary);
    setBlock(7, 13, 4, stairs(stoneStairs, "west"));
    setBlock(6, 14, 4, "minecraft:quartz_pillar[axis=y]");
    setBlock(5, 14, 4, stairs(stoneStairs, "east", "top"));
    setBlock(5, 15, 4, stonePrimary);
    setBlock(6, 15, 4, stairs(stoneStairs, "west"));
    setBlock(5, 16, 4, slab(stoneSlab, "bottom"));

    // Suspended Diamond Core
    setBlock(3, 12, 4, "minecraft:tinted_glass");
    setBlock(5, 12, 4, "minecraft:tinted_glass");

    setBlock(4, 10, 4, "minecraft:amethyst_block");
    setBlock(4, 11, 4, "minecraft:sea_lantern");
    setBlock(4, 11, 3, "minecraft:amethyst_block");
    setBlock(4, 11, 5, "minecraft:amethyst_block");

    setBlock(4, 12, 4, "minecraft:sea_lantern");
    setBlock(4, 12, 3, "minecraft:amethyst_block");
    setBlock(4, 12, 5, "minecraft:amethyst_block");
    placeCluster(4, 12, 2, "north");
    placeCluster(4, 12, 6, "south");

    setBlock(4, 13, 4, "minecraft:amethyst_block");
    setBlock(4, 13, 3, "minecraft:tinted_glass");
    setBlock(4, 13, 5, "minecraft:tinted_glass");

    setBlock(4, 14, 4, "minecraft:budding_amethyst");
    setBlock(4, 15, 4, "minecraft:amethyst_block");
    placeCluster(4, 16, 4, "up");

  } else if (variant === 3) {
    // --- VARIANT 3: Siege-Breaker War Pylon ---
    // Fortified Bastion
    for (let y = 9; y <= 10; y++) {
      for (let x = 2; x <= 6; x++) {
        for (let z = 2; z <= 6; z++) {
          const dx = Math.abs(x - cx);
          const dz = Math.abs(z - cz);
          if (dx === 2 || dz === 2) {
            if (y === 10) {
              setBlock(x, y, z, (dx === 2 && dz === 2) ? wall(stoneWall) : slab(stoneSlab, "bottom"));
            } else {
              setBlock(x, y, z, (z > cz && api.random() < 0.25) ? "minecraft:crying_obsidian" : "minecraft:quartz_bricks");
            }
          } else {
            setBlock(x, y, z, stonePrimary);
          }
        }
      }
    }
    setBlock(4, 9, 2, "minecraft:sea_lantern"); // seaward ward eye

    // Buttress Columns
    for (let y = 11; y <= 13; y++) {
      setBlock(2, y, 2, wall(stoneWall));
      setBlock(6, y, 2, wall(stoneWall));
      setBlock(2, y, 6, wall(stoneWall));
      setBlock(6, y, 6, wall(stoneWall));
    }

    // Forward-Leaning War Lance
    setBlock(4, 11, 4, "minecraft:sea_lantern");
    setBlock(3, 11, 4, "minecraft:amethyst_block");
    setBlock(5, 11, 4, "minecraft:amethyst_block");
    setBlock(4, 11, 3, "minecraft:amethyst_block");
    setBlock(4, 11, 5, "minecraft:crying_obsidian");

    setBlock(4, 12, 4, "minecraft:amethyst_block");
    setBlock(4, 12, 3, "minecraft:sea_lantern");
    setBlock(3, 12, 3, "minecraft:amethyst_block");
    setBlock(5, 12, 3, "minecraft:amethyst_block");

    setBlock(4, 13, 3, "minecraft:sea_lantern");
    setBlock(4, 13, 2, "minecraft:amethyst_block");
    setBlock(3, 13, 3, "minecraft:amethyst_block");
    setBlock(5, 13, 3, "minecraft:amethyst_block");

    setBlock(4, 14, 3, "minecraft:amethyst_block");
    setBlock(4, 14, 2, "minecraft:budding_amethyst");
    setBlock(3, 14, 2, "minecraft:tinted_glass");
    setBlock(5, 14, 2, "minecraft:tinted_glass");

    setBlock(4, 15, 2, "minecraft:amethyst_block");
    setBlock(4, 15, 3, "minecraft:budding_amethyst");
    setBlock(4, 16, 2, "minecraft:amethyst_block");
    placeCluster(4, 16, 1, "north");

    setBlock(4, 17, 2, "minecraft:budding_amethyst");
    placeCluster(4, 18, 2, "up");
    placeCluster(3, 15, 2, "west");
    placeCluster(5, 15, 2, "east");

  } else if (variant === 4) {
    // --- VARIANT 4: Quad-Star Resonance Obelisk ---
    // 4 Satellite Nodes
    const satellites = [
      { x: 4, z: 1, f: "north" },
      { x: 4, z: 7, f: "south" },
      { x: 1, z: 4, f: "west" },
      { x: 7, z: 4, f: "east" },
    ];
    satellites.forEach(s => {
      setBlock(s.x, 9, s.z, wall(stoneWall));
      setBlock(s.x, 10, s.z, wall(stoneWall));
      setBlock(s.x, 11, s.z, stairs(stoneStairs, s.f, "top"));
      setBlock(s.x, 12, s.z, "minecraft:sea_lantern");
      setBlock(s.x, 13, s.z, "minecraft:amethyst_block");
      placeCluster(s.x, 14, s.z, "up");
    });

    // Energy Bridges
    setBlock(4, 12, 2, "minecraft:tinted_glass");
    setBlock(4, 12, 3, "minecraft:tinted_glass");
    setBlock(4, 12, 5, "minecraft:tinted_glass");
    setBlock(4, 12, 6, "minecraft:tinted_glass");
    setBlock(2, 12, 4, "minecraft:tinted_glass");
    setBlock(3, 12, 4, "minecraft:tinted_glass");
    setBlock(5, 12, 4, "minecraft:tinted_glass");
    setBlock(6, 12, 4, "minecraft:tinted_glass");

    // Central Spire
    for (let y = 9; y <= 10; y++) {
      setBlock(4, y, 4, "minecraft:crying_obsidian");
      setBlock(4, y, 3, "minecraft:quartz_pillar[axis=y]");
      setBlock(4, y, 5, "minecraft:quartz_pillar[axis=y]");
      setBlock(3, y, 4, "minecraft:quartz_pillar[axis=y]");
      setBlock(5, y, 4, "minecraft:quartz_pillar[axis=y]");
    }
    for (let y = 11; y <= 13; y++) {
      setBlock(4, y, 4, "minecraft:sea_lantern");
    }
    setBlock(4, 14, 4, "minecraft:amethyst_block");
    setBlock(4, 14, 3, "minecraft:budding_amethyst");
    setBlock(4, 14, 5, "minecraft:budding_amethyst");
    setBlock(3, 14, 4, "minecraft:budding_amethyst");
    setBlock(5, 14, 4, "minecraft:budding_amethyst");

    setBlock(4, 15, 4, "minecraft:amethyst_block");
    placeCluster(4, 15, 3, "north");
    placeCluster(4, 15, 5, "south");
    placeCluster(3, 15, 4, "west");
    placeCluster(5, 15, 4, "east");

    setBlock(4, 16, 4, "minecraft:budding_amethyst");
    setBlock(4, 17, 4, "minecraft:amethyst_block");
    placeCluster(4, 18, 4, "up");

  } else {
    // --- VARIANT 5: Crown of the Sacred Bastion ---
    // 4 Spiral Columns
    const facings = ["north", "east", "south", "west"];
    for (let y = 9; y <= 12; y++) {
      const f = facings[(y - 9) % 4];
      setBlock(2, y, 2, stonePrimary);
      setBlock(6, y, 2, stonePrimary);
      setBlock(2, y, 6, stonePrimary);
      setBlock(6, y, 6, stonePrimary);
      setBlock(2, y, 3, stairs(stoneStairs, f));
      setBlock(6, y, 3, stairs(stoneStairs, f));
      setBlock(2, y, 5, stairs(stoneStairs, f));
      setBlock(6, y, 5, stairs(stoneStairs, f));
    }

    // Corona Dome Arch Ring
    for (let x = 2; x <= 6; x++) {
      setBlock(x, 13, 2, stairs(stoneStairs, "north", "top"));
      setBlock(x, 13, 6, stairs(stoneStairs, "south", "top"));
      setBlock(2, 13, x, stairs(stoneStairs, "west", "top"));
      setBlock(6, 13, x, stairs(stoneStairs, "east", "top"));
    }
    for (let x = 2; x <= 6; x++) {
      for (let z = 2; z <= 6; z++) {
        if (x === 2 || x === 6 || z === 2 || z === 6) {
          setBlock(x, 14, z, slab(stoneSlab, "bottom"));
        }
      }
    }

    // Grand Crystal Geode
    for (let y = 9; y <= 10; y++) {
      setBlock(4, y, 4, "minecraft:sea_lantern");
      setBlock(4, y, 3, "minecraft:quartz_pillar[axis=y]");
      setBlock(4, y, 5, "minecraft:quartz_pillar[axis=y]");
      setBlock(3, y, 4, "minecraft:quartz_pillar[axis=y]");
      setBlock(5, y, 4, "minecraft:quartz_pillar[axis=y]");
    }
    for (let y = 11; y <= 13; y++) {
      for (let x = 3; x <= 5; x++) {
        for (let z = 3; z <= 5; z++) {
          if (x === 4 && z === 4) {
            setBlock(x, y, z, "minecraft:sea_lantern");
          } else {
            setBlock(x, y, z, "minecraft:amethyst_block");
          }
        }
      }
    }

    // Geode Piercing Roof
    for (let x = 3; x <= 5; x++) {
      for (let z = 3; z <= 5; z++) {
        setBlock(x, 14, z, (x === 4 && z === 4) ? "minecraft:sea_lantern" : "minecraft:amethyst_block");
      }
    }
    setBlock(4, 15, 4, "minecraft:amethyst_block");
    setBlock(4, 15, 3, "minecraft:amethyst_block");
    setBlock(4, 15, 5, "minecraft:amethyst_block");
    setBlock(3, 15, 4, "minecraft:amethyst_block");
    setBlock(5, 15, 4, "minecraft:amethyst_block");

    setBlock(4, 16, 4, "minecraft:budding_amethyst");
    placeCluster(4, 16, 3, "north");
    placeCluster(4, 16, 5, "south");
    placeCluster(3, 16, 4, "west");
    placeCluster(5, 16, 4, "east");

    setBlock(4, 17, 4, "minecraft:amethyst_block");
    placeCluster(4, 18, 4, "up");
  }

  // Final deterministic write
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const b = grid[x][y][z];
        if (b !== null) {
          api.set(x, y, z, b);
        }
      }
    }
  }

  return {
    name: "warding_crystal_pylon",
    seatY: seatY,
    anchors: {
      front: [cx, baseDeckY, 0]
    }
  };
}
